// authored, awaiting local run.
//
// ScanLibrary usecase tests (`lib/domain/usecases/scan_library.dart`) run
// against the REAL fixture files under test/fixtures/audio/ (10 files:
// 6 MP3 + 4 FLAC, generated by tools/gen_fixtures.py with ID3v2.3 /
// Vorbis tags, USLT + LYRICS synced lyrics, APIC + PICTURE PNG covers).
// The scanner reads dart:io files and parses on background isolates —
// both work on the host `flutter test` VM.
//
// Covered: the ScanEvent stream contract (ScanStarted first, per-file
// trackFound/progress, ScanCompleted last), correct tags for all ten
// fixtures, embedded synced lyrics persisted via LyricsDao, cover art
// written into the covers dir, idempotent re-scan (upsert preserves ids
// and play stats), missing-folder behaviour and unsupported extensions.
import 'dart:io';

import 'package:drift/native.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:wavely/data/local/db/app_database.dart';
import 'package:wavely/data/local/db/daos/lyrics_dao.dart';
import 'package:wavely/domain/entities/entities.dart';
import 'package:wavely/domain/usecases/scan_library.dart';

const String _pngMagic = '89 50 4e 47 0d 0a 1a 0a';

/// (title, artist, album, genre) per test/fixtures/audio fixture plan
/// (tools/gen_fixtures.py).
const List<(String, String, String, String)> _expectedFixtures = <(
  String,
  String,
  String,
  String,
)>[
  ('Neon Rivers', 'Aria Wave', 'Chromatic', 'Electronic'),
  ('Glass Harbour', 'Aria Wave', 'Chromatic', 'Electronic'),
  ('Midnight Transit', 'Kodo Line', 'Night Drive', 'Ambient'),
  ('Copper Skies', 'Kodo Line', 'Night Drive', 'Ambient'),
  ('Violet Static', 'Mirren Vale', 'Hush', 'Indie'),
  ('Paper Lanterns', 'Mirren Vale', 'Hush', 'Indie'),
  ('Paper Boats', 'Marina Fold', 'Tidelines', 'Indie'),
  ('Tideline', 'Marina Fold', 'Tidelines', 'Indie'),
  ('Salt and Cedar', 'Jonah Reave', 'Northlight', 'Folk'),
  ('Northbound', 'Jonah Reave', 'Northlight', 'Folk'),
];

final bool _fixturesPresent = Directory('test/fixtures/audio').existsSync();

Future<List<ScanEvent>> _runScan(
  ScanLibrary scanner, {
  required List<String> folders,
  String? coversDir,
}) async {
  final events = <ScanEvent>[];
  await for (final event
      in scanner.scan(folders: folders, coversDir: coversDir)) {
    events.add(event);
  }
  return events;
}

List<Track> _foundTracks(List<ScanEvent> events) => <Track>[
      for (final event in events)
        if (event is TrackFound) event.track,
    ];

void main() {
  late AppDatabase db;
  late Directory coversDir;

  setUp(() async {
    db = AppDatabase(NativeDatabase.memory());
    coversDir = await Directory.systemTemp.createTemp('wavely_covers');
  });

  tearDown(() async {
    await db.close();
    if (coversDir.existsSync()) {
      await coversDir.delete(recursive: true);
    }
  });

  group('ScanLibrary on the real fixtures', () {
    ScanLibrary scanner() => ScanLibrary(
          tracksDao: db.tracksDao,
          lyricsDao: db.lyricsDao,
        );

    test(
      'scans test/fixtures/audio into 10 tagged tracks',
      () async {
        final events = await _runScan(
          scanner(),
          folders: <String>['test/fixtures/audio'],
          coversDir: coversDir.path,
        );

        // Stream contract: ScanStarted first, ScanCompleted last.
        expect(events.first, isA<ScanStarted>());
        expect((events.first as ScanStarted).root, 'test/fixtures/audio');
        expect(events.last, isA<ScanCompleted>());
        expect((events.last as ScanCompleted).count, 10);
        expect((events.last as ScanCompleted).errors, isEmpty);

        final tracks = _foundTracks(events);
        expect(tracks, hasLength(10));
        expect(
          events.whereType<ScanProgress>(),
          hasLength(10),
        );
        for (final progress in events.whereType<ScanProgress>()) {
          expect(progress.total, 10);
        }

        final titles = tracks.map((t) => t.title).toSet();
        expect(
          titles,
          _expectedFixtures.map((f) => f.$1).toSet(),
        );
        for (final track in tracks) {
          expect(track.sourceId, Track.localSourceId);
          expect(track.sourceTrackId, isNotEmpty);
          expect(track.filePath, isNotNull);
          expect(track.format, anyOf('mp3', 'flac'));
          expect(track.durationMs, greaterThanOrEqualTo(0));
        }
      },
      skip: _fixturesPresent
          ? false
          : 'test/fixtures/audio fixtures are missing (run '
              'tools/gen_fixtures.py)',
    );

    test(
      'every fixture lands with its tagged artist / album / genre',
      () async {
        final events = await _runScan(
          scanner(),
          folders: <String>['test/fixtures/audio'],
        );
        final tracks = _foundTracks(events);
        expect(tracks, hasLength(10));

        for (final (title, artist, album, genre) in _expectedFixtures) {
          final match = tracks.singleWhere((t) => t.title == title);
          expect(match.artist, artist, reason: 'artist for "$title"');
          expect(match.album, album, reason: 'album for "$title"');
          expect(match.genre, genre, reason: 'genre for "$title"');
        }
      },
      skip: _fixturesPresent ? false : 'fixtures missing',
    );

    test(
      'embedded synced lyrics are stored under the embedded provider',
      () async {
        final events = await _runScan(
          scanner(),
          folders: <String>['test/fixtures/audio'],
        );
        final tracks = _foundTracks(events);
        expect(tracks, hasLength(10));

        for (final track in tracks) {
          final row = await db.lyricsDao.get(
            trackId: track.id!,
            provider: LyricsDao.embeddedProvider,
          );
          expect(row, isNotNull, reason: 'lyrics for "${track.title}"');
          // The fixture lyrics are LRC-tagged -> stored as syncedLrc.
          expect(row!.syncedLrc, isNotNull);
          expect(row.syncedLrc, contains('[00:01.00]'));
          expect(row.syncedLrc, contains('First line of'));
          expect(row.plainText, isNull);
        }
      },
      skip: _fixturesPresent ? false : 'fixtures missing',
    );

    test(
      'embedded covers are written into the covers dir as PNG files',
      () async {
        final events = await _runScan(
          scanner(),
          folders: <String>['test/fixtures/audio'],
          coversDir: coversDir.path,
        );
        final tracks = _foundTracks(events);
        expect(tracks, hasLength(10));

        for (final track in tracks) {
          final coverPath = track.coverPath;
          expect(coverPath, isNotNull, reason: 'cover for "${track.title}"');
          final file = File(coverPath!);
          expect(file.existsSync(), isTrue);
          expect(file.parent.path, coversDir.path);
          expect(coverPath.endsWith('.png'), isTrue,
              reason: 'PNG mime maps to the .png extension');
          final bytes = await file.readAsBytes();
          final magic = bytes
              .take(8)
              .map((b) => b.toRadixString(16).padLeft(2, '0'))
              .join(' ');
          expect(magic, _pngMagic);
        }
      },
      skip: _fixturesPresent ? false : 'fixtures missing',
    );

    test(
      're-scan is idempotent: upserts keep ids and play statistics',
      () async {
        final scan = scanner();
        final first = _foundTracks(await _runScan(
          scan,
          folders: <String>['test/fixtures/audio'],
        ));
        expect(first, hasLength(10));
        expect(await db.tracksDao.countAll(), 10);
        expect(await db.tracksDao.countBySource(Track.localSourceId), 10);

        // Simulate listening activity between the scans.
        await db.playsDao.incrementTrackPlayStats(first.first.id!);

        final second = _foundTracks(await _runScan(
          scan,
          folders: <String>['test/fixtures/audio'],
        ));
        expect((await db.tracksDao.countAll()), 10); // no duplicates
        expect(
          second.map((t) => t.id).toSet(),
          first.map((t) => t.id).toSet(),
        );

        final updated = await db.tracksDao.getById(first.first.id!);
        expect(updated!.playCount, 1); // upsert preserved the stat
      },
      skip: _fixturesPresent ? false : 'fixtures missing',
    );

    test(
      'artist + album projections are kept in sync',
      () async {
        await _runScan(
          scanner(),
          folders: <String>['test/fixtures/audio'],
        );
        final artists = await db.tracksDao.distinctArtists();
        expect(artists.map((a) => a.name).toSet(), <String>{
          'Aria Wave',
          'Kodo Line',
          'Mirren Vale',
          'Marina Fold',
          'Jonah Reave',
        });
        final albums = await db.tracksDao.distinctAlbums();
        expect(albums.map((a) => a.title).toSet(), <String>{
          'Chromatic',
          'Night Drive',
          'Hush',
          'Tidelines',
          'Northlight',
        });
      },
      skip: _fixturesPresent ? false : 'fixtures missing',
    );

    test('a missing folder completes empty without errors', () async {
      final events = await _runScan(
        scanner(),
        folders: <String>['/definitely/not/a/wavely/folder'],
      );
      expect(events, hasLength(2));
      expect(events.first, isA<ScanStarted>());
      final completed = events.last as ScanCompleted;
      expect(completed.count, 0);
      expect(completed.errors, isEmpty);
      expect(await db.tracksDao.countAll(), 0);
    });

    test('unsupported extensions are ignored silently', () async {
      final temp = await Directory.systemTemp.createTemp('wavely_scan');
      await File('${temp.path}/notes.txt').writeAsString('not audio');
      addTearDown(() => temp.delete(recursive: true));

      final events = await _runScan(
        scanner(),
        folders: <String>[temp.path],
      );
      final completed = events.last as ScanCompleted;
      expect(completed.count, 0);
      expect(events.whereType<ScanError>(), isEmpty);
      expect(events.whereType<TrackFound>(), isEmpty);
    });
  });
}
